        double precio = 0;
        boolean valido = false;
        while (!valido) {
            System.out.println("Precio no negativo con punto:");
            if (scanner.hasNextDouble()) {
                precio = scanner.nextDouble();
                scanner.nextLine();
                valido = Double.isFinite(precio) && precio >= 0;
                if (!valido) {
                    System.out.println("Precio no permitido");

