        System.out.println("Suma: " + suma);
        scanner.close();
    }
}

import java.util.Scanner;
public class Compra {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalCentimos = 0;
        int cantidad = 0;
        int opcion;
        do {
            System.out.println("1. Agua 150 ct | 2. Zumo 200 ct | 0. Fin");
            opcion = Integer.parseInt(scanner.nextLine());
            switch (opcion) {
                case 1 -> {
                    totalCentimos += 150;
                    cantidad++;
                }
                case 2 -> {

                    totalCentimos += 200;
                    cantidad++;
                }
                case 0 -> System.out.println("Compra terminada");
                default -> System.out.println("Opcion no valida");
            }
        } while (opcion != 0);
        System.out.println("Productos: " + cantidad);
        System.out.println("Total en centimos: " + totalCentimos);
        scanner.close();
    }
}
